export const SYMBOLS = {
  X: 'X',
  O: 'O'
} as const;

export const GAME_MODES = {
  PVP: 'PVP',
  CPU: 'CPU'
} as const;

export const GAME_STATUS = {
  IN_PROGRESS: 'IN_PROGRESS',
  WIN: 'WIN',
  DRAW: 'DRAW'
} as const;

export const WINNING_LINES = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6]
] as const;

export type SymbolValue = typeof SYMBOLS[keyof typeof SYMBOLS];
export type GameMode = typeof GAME_MODES[keyof typeof GAME_MODES];
export type GameStatusValue = typeof GAME_STATUS[keyof typeof GAME_STATUS];
export type CellValue = SymbolValue | null;

export const INITIAL_BOARD: CellValue[] = Array(9).fill(null);
export const STORAGE_KEY = 'tictactoe.scoreboard.v1';

import { GAME_STATUS, WINNING_LINES, type CellValue, type GameStatusValue, type SymbolValue } from '../constants/gameConstants';

export interface WinDetectionResult {
  status: GameStatusValue;
  winner: SymbolValue | null;
  winningLine: readonly number[] | null;
}

export function detectWin(board: CellValue[]): WinDetectionResult {
  for (const line of WINNING_LINES) {
    const [a, b, c] = line;
    const value = board[a];
    if (value && value === board[b] && value === board[c]) {
      return { status: GAME_STATUS.WIN, winner: value, winningLine: line };
    }
  }

  if (board.every((cell) => cell !== null)) {
    return { status: GAME_STATUS.DRAW, winner: null, winningLine: null };
  }

  return { status: GAME_STATUS.IN_PROGRESS, winner: null, winningLine: null };
}

import { GAME_STATUS, SYMBOLS, type CellValue, type SymbolValue } from '../constants/gameConstants';
import { detectWin } from './winDetection';

const CPU: SymbolValue = SYMBOLS.O;
const HUMAN: SymbolValue = SYMBOLS.X;

function availableMoves(board: CellValue[]): number[] {
  return board.flatMap((cell, index) => (cell === null ? [index] : []));
}

function scoreTerminal(board: CellValue[], depth: number): number | null {
  const result = detectWin(board);
  if (result.status === GAME_STATUS.WIN) {
    if (result.winner === CPU) return 10 - depth;
    if (result.winner === HUMAN) return depth - 10;
  }
  if (result.status === GAME_STATUS.DRAW) return 0;
  return null;
}

function minimax(board: CellValue[], isMaximizing: boolean, depth: number): number {
  const terminalScore = scoreTerminal(board, depth);
  if (terminalScore !== null) return terminalScore;

  const moves = availableMoves(board);
  if (isMaximizing) {
    let bestScore = -Infinity;
    for (const move of moves) {
      const nextBoard = [...board];
      nextBoard[move] = CPU;
      bestScore = Math.max(bestScore, minimax(nextBoard, false, depth + 1));
    }
    return bestScore;
  }

  let bestScore = Infinity;
  for (const move of moves) {
    const nextBoard = [...board];
    nextBoard[move] = HUMAN;
    bestScore = Math.min(bestScore, minimax(nextBoard, true, depth + 1));
  }
  return bestScore;
}

export function getBestMove(board: CellValue[]): number {
  const moves = availableMoves(board);
  if (moves.length === 0) return -1;

  let bestMove = moves[0];
  let bestScore = -Infinity;

  for (const move of moves) {
    const nextBoard = [...board];
    nextBoard[move] = CPU;
    const score = minimax(nextBoard, false, 1);
    if (score > bestScore) {
      bestScore = score;
      bestMove = move;
    }
  }

  return bestMove;
}

import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { GAME_MODES, GAME_STATUS, INITIAL_BOARD, STORAGE_KEY, SYMBOLS, type CellValue, type GameMode, type GameStatusValue, type SymbolValue } from '../constants/gameConstants';
import type { WinDetectionResult } from '../engine/winDetection';

export interface ScoreboardState {
  xWins: number;
  oWins: number;
  draws: number;
}

export interface GameState {
  board: CellValue[];
  currentTurn: SymbolValue;
  status: GameStatusValue;
  winner: SymbolValue | null;
  selectedMode: GameMode | null;
  winningLine: readonly number[] | null;
  scoreboard: ScoreboardState;
  hydrated: boolean;
}

const initialScoreboard = (): ScoreboardState => {
  if (typeof window === 'undefined') return { xWins: 0, oWins: 0, draws: 0 };
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return { xWins: 0, oWins: 0, draws: 0 };
    const parsed = JSON.parse(raw) as ScoreboardState;
    return {
      xWins: Number(parsed.xWins) || 0,
      oWins: Number(parsed.oWins) || 0,
      draws: Number(parsed.draws) || 0
    };
  } catch {
    return { xWins: 0, oWins: 0, draws: 0 };
  }
};

const initialState: GameState = {
  board: [...INITIAL_BOARD],
  currentTurn: SYMBOLS.X,
  status: GAME_STATUS.IN_PROGRESS,
  winner: null,
  selectedMode: null,
  winningLine: null,
  scoreboard: initialScoreboard(),
  hydrated: true
};

const persistScoreboard = (scoreboard: ScoreboardState): void => {
  if (typeof window === 'undefined') return;
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(scoreboard));
};

const slice = createSlice({
  name: 'game',
  initialState,
  reducers: {
    setMode(state, action: PayloadAction<GameMode>) {
      state.selectedMode = action.payload;
      state.board = [...INITIAL_BOARD];
      state.currentTurn = SYMBOLS.X;
      state.status = GAME_STATUS.IN_PROGRESS;
      state.winner = null;
      state.winningLine = null;
    },
    placeSymbol(state, action: PayloadAction<number>) {
      const index = action.payload;
      if (state.status !== GAME_STATUS.IN_PROGRESS || state.board[index]) return;
      state.board[index] = state.currentTurn;
    },
    advanceTurn(state) {
      state.currentTurn = state.currentTurn === SYMBOLS.X ? SYMBOLS.O : SYMBOLS.X;
    },
    applyOutcome(state, action: PayloadAction<WinDetectionResult>) {
      state.status = action.payload.status;
      state.winner = action.payload.winner;
      state.winningLine = action.payload.winningLine;
      if (action.payload.status === GAME_STATUS.WIN) {
        if (action.payload.winner === SYMBOLS.X) state.scoreboard.xWins += 1;
        if (action.payload.winner === SYMBOLS.O) state.scoreboard.oWins += 1;
      }
      if (action.payload.status === GAME_STATUS.DRAW) {
        state.scoreboard.draws += 1;
      }
      persistScoreboard(state.scoreboard);
    },
    resetBoard(state) {
      state.board = [...INITIAL_BOARD];
      state.currentTurn = SYMBOLS.X;
      state.status = GAME_STATUS.IN_PROGRESS;
      state.winner = null;
      state.winningLine = null;
    },
    hydrateScoreboard(state) {
      state.scoreboard = initialScoreboard();
      state.hydrated = true;
    }
  }
});

export const { setMode, placeSymbol, advanceTurn, applyOutcome, resetBoard, hydrateScoreboard } = slice.actions;
export const gameReducer = slice.reducer;

import { configureStore } from '@reduxjs/toolkit';
import { gameReducer } from './gameSlice';

export const store = configureStore({
  reducer: {
    game: gameReducer
  }
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { advanceTurn, applyOutcome, placeSymbol, type GameState } from '../store/gameSlice';
import type { AppDispatch, RootState } from '../store/store';
import { GAME_MODES, GAME_STATUS, SYMBOLS } from '../constants/gameConstants';
import { detectWin } from '../engine/winDetection';
import { getBestMove } from '../engine/minimax';

export function useGameState() {
  const dispatch = useDispatch<AppDispatch>();
  const game = useSelector((state: RootState) => state.game);

  const evaluateBoard = (board: GameState['board']) => {
    const result = detectWin(board);
    if (result.status !== GAME_STATUS.IN_PROGRESS) {
      dispatch(applyOutcome(result));
      return result;
    }
    return result;
  };

  const handleCellClick = (index: number) => {
    if (game.status !== GAME_STATUS.IN_PROGRESS) return;
    if (game.board[index]) return;
    if (game.selectedMode === null) return;
    if (game.selectedMode === GAME_MODES.CPU && game.currentTurn === SYMBOLS.O) return;

    dispatch(placeSymbol(index));
    const nextBoard = [...game.board];
    nextBoard[index] = game.currentTurn;
    const result = detectWin(nextBoard);
    if (result.status !== GAME_STATUS.IN_PROGRESS) {
      dispatch(applyOutcome(result));
      return;
    }

    dispatch(advanceTurn());
  };

  useEffect(() => {
    if (game.selectedMode !== GAME_MODES.CPU) return;
    if (game.status !== GAME_STATUS.IN_PROGRESS) return;
    if (game.currentTurn !== SYMBOLS.O) return;

    const timer = window.setTimeout(() => {
      const move = getBestMove(game.board);
      if (move < 0) return;
      dispatch(placeSymbol(move));
      const nextBoard = [...game.board];
      nextBoard[move] = SYMBOLS.O;
      const result = detectWin(nextBoard);
      if (result.status !== GAME_STATUS.IN_PROGRESS) {
        dispatch(applyOutcome(result));
        return;
      }
      dispatch(advanceTurn());
    }, 350);

    return () => window.clearTimeout(timer);
  }, [game.selectedMode, game.currentTurn, game.status, game.board, dispatch]);

  return {
    game,
    handleCellClick,
    evaluateBoard
  };
}

import { Navigate, Route, Routes, useNavigate } from 'react-router-dom';
import { useEffect } from 'react';
import { useSelector } from 'react-redux';
import { ModeSelector } from './components/ModeSelector';
import { Scoreboard } from './components/Scoreboard';
import { GameStatus } from './components/GameStatus';
import { Board } from './components/Board';
import { ResetButton } from './components/ResetButton';
import { useGameState } from './hooks/useGameState';
import { GAME_MODES } from './constants/gameConstants';
import { setMode, resetBoard } from './store/gameSlice';
import type { RootState } from './store/store';
import { useDispatch } from 'react-redux';

function SetupPage() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const selectedMode = useSelector((state: RootState) => state.game.selectedMode);

  useEffect(() => {
    document.title = 'Tic Tac Toe - Setup';
  }, []);

  return (
    <main aria-label="Game setup screen" className="mx-auto flex min-h-screen max-w-3xl flex-col items-center justify-center gap-6 px-4 py-10">
      <section className="w-full rounded-lg bg-white p-6 shadow-sm">
        <h1 className="text-3xl font-semibold tracking-tight text-slate-900">Tic Tac Toe</h1>
        <p className="mt-2 text-sm text-slate-600">Choose a mode to start a new match.</p>
        <div className="mt-6">
          <ModeSelector
            selectedMode={selectedMode}
            onSelect={(mode) => dispatch(setMode(mode))}
          />
        </div>
        <button
          type="button"
          aria-label="Start game"
          disabled={selectedMode === null}
          onClick={() => navigate('/play')}
          className="mt-6 inline-flex w-full items-center justify-center rounded bg-blue-600 px-4 py-3 text-sm font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300"
        >
          Start Game
        </button>
      </section>
    </main>
  );
}

function PlayPage() {
  const dispatch = useDispatch();
  const { game, handleCellClick } = useGameState();

  useEffect(() => {
    document.title = 'Tic Tac Toe - Play';
  }, []);

  if (!game.selectedMode) {
    return <Navigate to="/setup" replace />;
  }

  return (
    <main aria-label="Active game board" className="mx-auto flex min-h-screen max-w-3xl flex-col gap-4 px-4 py-6">
      <header className="rounded-lg bg-white p-4 shadow-sm">
        <h1 className="text-2xl font-semibold text-slate-900">Tic Tac Toe</h1>
        <p className="mt-1 text-sm text-slate-600">Mode: {game.selectedMode === GAME_MODES.CPU ? 'Unbeatable CPU' : 'Local PvP'}</p>
      </header>

      <Scoreboard scoreboard={game.scoreboard} />
      <GameStatus status={game.status} currentTurn={game.currentTurn} winner={game.winner} />
      <Board board={game.board} winningLine={game.winningLine} onCellClick={handleCellClick} disabled={game.status !== 'IN_PROGRESS'} />
      <ResetButton onClick={() => dispatch(resetBoard())} />
    </main>
  );
}

export function App() {
  return (
    <Routes>
      <Route path="/setup" element={<SetupPage />} />
      <Route path="/play" element={<PlayPage />} />
      <Route path="*" element={<Navigate to="/setup" replace />} />
    </Routes>
  );
}

import { GAME_MODES, type GameMode } from '../constants/gameConstants';

interface ModeSelectorProps {
  selectedMode: GameMode | null;
  onSelect: (mode: GameMode) => void;
}

export function ModeSelector({ selectedMode, onSelect }: ModeSelectorProps) {
  return (
    <fieldset aria-label="Select game mode" className="w-full">
      <legend className="sr-only">Select game mode</legend>
      <div className="flex flex-col gap-3 sm:flex-row">
        <button
          type="button"
          aria-label="Local Player vs Player option"
          aria-pressed={selectedMode === GAME_MODES.PVP}
          onClick={() => onSelect(GAME_MODES.PVP)}
          className={`flex-1 rounded border px-4 py-3 text-sm font-medium transition focus:outline-none focus:ring-2 focus:ring-blue-500 ${selectedMode === GAME_MODES.PVP ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-300 bg-white text-slate-700 hover:border-blue-400'}`}
        >
          Local PvP
        </button>
        <button
          type="button"
          aria-label="Unbeatable CPU option"
          aria-pressed={selectedMode === GAME_MODES.CPU}
          onClick={() => onSelect(GAME_MODES.CPU)}
          className={`flex-1 rounded border px-4 py-3 text-sm font-medium transition focus:outline-none focus:ring-2 focus:ring-blue-500 ${selectedMode === GAME_MODES.CPU ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-300 bg-white text-slate-700 hover:border-blue-400'}`}
        >
          Vs CPU
        </button>
      </div>
    </fieldset>
  );
}

import type { CellValue } from '../constants/gameConstants';

interface CellProps {
  index: number;
  value: CellValue;
  isWinningCell?: boolean;
  disabled?: boolean;
  onClick: () => void;
}

export function Cell({ index, value, isWinningCell = false, disabled = false, onClick }: CellProps) {
  const label = value ? `Marked cell ${index + 1} with ${value}` : `Cell ${index + 1}, place X or O`;
  return (
    <button
      type="button"
      aria-label={label}
      aria-disabled={disabled || Boolean(value)}
      disabled={disabled || Boolean(value)}
      onClick={onClick}
      className={`flex aspect-square items-center justify-center rounded-lg border text-3xl font-semibold transition focus:outline-none focus:ring-2 focus:ring-blue-500 ${isWinningCell ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-300 bg-white text-slate-900 hover:border-blue-400'} ${value ? 'cursor-default' : 'cursor-pointer'} disabled:cursor-not-allowed disabled:opacity-90`}
    >
      <span aria-hidden="true">{value ?? ''}</span>
    </button>
  );
}

import type { CellValue } from '../constants/gameConstants';
import { Cell } from './Cell';

interface BoardProps {
  board: CellValue[];
  winningLine: readonly number[] | null;
  disabled?: boolean;
  onCellClick: (index: number) => void;
}

export function Board({ board, winningLine, disabled = false, onCellClick }: BoardProps) {
  return (
    <section aria-label="Tic-Tac-Toe 3x3 grid" className="rounded-lg bg-white p-4 shadow-sm">
      <div className="grid grid-cols-3 gap-2">
        {board.map((value, index) => (
          <Cell
            key={index}
            index={index}
            value={value}
            disabled={disabled}
            isWinningCell={Boolean(winningLine?.includes(index))}
            onClick={() => onCellClick(index)}
          />
        ))}
      </div>
    </section>
  );
}

import { GAME_STATUS, SYMBOLS, type GameStatusValue, type SymbolValue } from '../constants/gameConstants';

interface GameStatusProps {
  status: GameStatusValue;
  currentTurn: SymbolValue;
  winner: SymbolValue | null;
}

export function GameStatus({ status, currentTurn, winner }: GameStatusProps) {
  let message = '';
  if (status === GAME_STATUS.IN_PROGRESS) {
    message = `Current turn: ${currentTurn}`;
  } else if (status === GAME_STATUS.WIN) {
    message = `Winner: ${winner}`;
  } else {
    message = 'Game ended in a draw';
  }

  return (
    <section aria-label="Current turn indicator" className="rounded-lg bg-white p-4 shadow-sm">
      <p className="text-sm font-medium text-slate-700">{message}</p>
      {status === GAME_STATUS.IN_PROGRESS && currentTurn === SYMBOLS.O && (
        <p className="mt-1 text-xs text-slate-500">CPU thinking may appear briefly in CPU mode.</p>
      )}
    </section>
  );
}

import type { ScoreboardState } from '../store/gameSlice';

interface ScoreboardProps {
  scoreboard: ScoreboardState;
}

export function Scoreboard({ scoreboard }: ScoreboardProps) {
  return (
    <section aria-label="Player scores" className="rounded-lg bg-white p-4 shadow-sm">
      <div className="grid grid-cols-3 gap-3 text-center text-sm">
        <div className="rounded bg-slate-100 p-3">
          <div className="font-semibold text-slate-900">X Wins</div>
          <div className="mt-1 text-2xl font-semibold text-blue-700">{scoreboard.xWins}</div>
        </div>
        <div className="rounded bg-slate-100 p-3">
          <div className="font-semibold text-slate-900">O Wins</div>
          <div className="mt-1 text-2xl font-semibold text-blue-700">{scoreboard.oWins}</div>
        </div>
        <div className="rounded bg-slate-100 p-3">
          <div className="font-semibold text-slate-900">Draws</div>
          <div className="mt-1 text-2xl font-semibold text-blue-700">{scoreboard.draws}</div>
        </div>
      </div>
    </section>
  );
}

interface ResetButtonProps {
  onClick: () => void;
}

export function ResetButton({ onClick }: ResetButtonProps) {
  return (
    <button
      type="button"
      aria-label="Reset match"
      onClick={onClick}
      className="rounded bg-red-600 px-4 py-3 text-sm font-medium text-white transition hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500"
    >
      Reset Match
    </button>
  );
}

